// PS side of the CSR test UC2 (Zynq profile, point 4): same program, new input data.
// The Cortex-A9 #0 loads the CPU program once at the boot address, as in UC1, then runs it
// RUNS times: the first run from IDLE, the next ones from DONE with RESET CPU and new data only.
// Each command is printed with the STATUS read after it.
// The CPU side is sw/SoC/examples/ps_csr_uc2.
#include <stdint.h>
#include "ps_hw.h"        // generated by build_ps_app.py from the XSA
#include "cpu_program.h"  // generated by build_ps_app.py from the CPU program
#include "xil_printf.h"
#include "simplyv_conf.h"
#include "simplyv_csr_host.h"
#include "ps_csr_uc2.h"

// Reads of STATUS before the timeout: much longer than the job of the CPU
#define MAX_POLLS (10000000u)

// Runs of the program: the first one after the load, the others are UC2
#define RUNS (3u)

// The CPU program is linked at the start of BRAM_0
#define BOOT_ADDR ((uint32_t)_peripheral_BRAM_0_start)

// Name of a state, for the prints
static const char *state_name(uint32_t status)
{
    switch (status) {
        case CSR_ST_IDLE:  return "IDLE";
        case CSR_ST_BUSY:  return "BUSY";
        case CSR_ST_DONE:  return "DONE";
        case CSR_ST_ERROR: return "ERROR";
        case CSR_ST_HALT:  return "HALT";
        case CSR_TIMEOUT:  return "TIMEOUT";
        default:           return "UNKNOWN";
    }
}

int main(void)
{
    // Boot address and data in BRAM_0, as seen by the PS
    volatile uint32_t *program = (volatile uint32_t *)(uintptr_t)(PS_M_AXI_GP0_BASEADDR + BOOT_ADDR);
    uint32_t cpu_data = (uint32_t)(_peripheral_BRAM_0_start + PS_CSR_DATA_OFFSET);
    volatile uint32_t *data = (volatile uint32_t *)(uintptr_t)(PS_M_AXI_GP0_BASEADDR + cpu_data);
    uint32_t ptr_in  = cpu_data + 4u * PS_CSR_IN;
    uint32_t ptr_out = cpu_data + 4u * PS_CSR_OUT;
    uint32_t status;
    uint32_t value;
    uint32_t errors = 0;

    xil_printf("[PS] CSR at 0x%08x\r\n", (uint32_t)CSR_HOST_BASEADDR);

    // The program must not overlap the data
    if (BOOT_ADDR + 4u * CPU_PROGRAM_WORDS > cpu_data) {
        xil_printf("[PS] ERROR: program of %u bytes overlaps the data\r\n", 4u * CPU_PROGRAM_WORDS);
        return 1;
    }

    for (uint32_t run = 0; run < RUNS; run++) {
        xil_printf("[PS] --- Run %u, STATUS %s ---\r\n", run, state_name(csr_status()));

        // 1. Stop the CPU
        csr_reset_cpu();
        status = csr_status();
        xil_printf("[PS] RESET CPU       -> STATUS %s\r\n", state_name(status));
        if (status != CSR_ST_IDLE) {
            xil_printf("[PS] ERROR: expected IDLE\r\n");
            return 1;
        }

        // 2. Only the first time: LOAD PROGRAM, then copy the program and read it back
        if (run == 0) {
            csr_load_program(BOOT_ADDR);
            for (uint32_t i = 0; i < CPU_PROGRAM_WORDS; i++) {
                program[i] = cpu_program[i];
            }
            for (uint32_t i = 0; i < CPU_PROGRAM_WORDS; i++) {
                if (program[i] != cpu_program[i]) {
                    errors++;
                }
            }
            xil_printf("[PS] LOAD PROGRAM    -> STATUS %s (%u bytes at BOOT_ADDR 0x%08x, %u errors on read back)\r\n",
                       state_name(csr_status()), 4u * CPU_PROGRAM_WORDS, BOOT_ADDR, errors);
            if (errors != 0) {
                xil_printf("[PS] ERROR: program not written correctly\r\n");
                return 1;
            }
        }

        // 3. New input data, then the pointers seen by the CPU
        data[PS_CSR_IN]  = PS_CSR_TEST_VALUE + run;
        data[PS_CSR_OUT] = 0;
        csr_load_input_data(ptr_in, ptr_out);
        xil_printf("[PS] LOAD INPUT DATA -> STATUS %s (input 0x%08x, PTR_IN 0x%08x, PTR_OUT 0x%08x)\r\n",
                   state_name(csr_status()), PS_CSR_TEST_VALUE + run, ptr_in, ptr_out);

        // 4. Start the CPU and wait for the end of the job
        csr_run();
        xil_printf("[PS] RUN             -> STATUS %s\r\n", state_name(csr_status()));
        status = csr_wait(MAX_POLLS);
        xil_printf("[PS] Wait            -> STATUS %s\r\n", state_name(status));
        if (status != CSR_ST_DONE) {
            xil_printf("[PS] ERROR: expected DONE\r\n");
            return 1;
        }

        // 5. Check the output
        value = data[PS_CSR_OUT];
        xil_printf("[PS] Output 0x%08x at PTR_OUT\r\n", value);
        if (value != ~(PS_CSR_TEST_VALUE + run)) {
            xil_printf("[PS] ERROR: expected 0x%08x\r\n", ~(PS_CSR_TEST_VALUE + run));
            return 1;
        }
    }

    xil_printf("[PS] Test passed\r\n");
    return 0;
}
